import os
from azure.storage.blob import BlobServiceClient
from dotenv import load_dotenv

class StorageClient:
    _blob_service_client: BlobServiceClient = None

    def __init__(self):
        load_dotenv()
        if not StorageClient._blob_service_client:
            connection_string = os.getenv("AZURE_STORAGE_CONNECTION_STRING")
            if not connection_string:
                raise ValueError("AZURE_STORAGE_CONNECTION_STRING environment variable not set.")
            StorageClient._blob_service_client = BlobServiceClient.from_connection_string(connection_string)

    def get_blob_service_client(self) -> BlobServiceClient:
        return StorageClient._blob_service_client

from storage_client import StorageClient
from storage_models import UploadObjectRequest, UploadObjectResponse
from azure.core.exceptions import ResourceExistsError

def upload_object(request: UploadObjectRequest) -> UploadObjectResponse:
    client = StorageClient().get_blob_service_client()
    blob_client = client.get_blob_client(container=request.container_name, blob=request.blob_name)

    try:
        blob_client.upload_blob(request.data, overwrite=True, content_settings=request.content_settings)
        properties = blob_client.get_blob_properties()
        return UploadObjectResponse(
            message="Object uploaded successfully",
            etag=properties.etag
        )
    except ResourceExistsError:
        properties = blob_client.get_blob_properties()
        return UploadObjectResponse(
            message="Object already exists, overwritten successfully",
            etag=properties.etag
        )
    except Exception as e:
        raise RuntimeError(f"Failed to upload object: {e}")

from storage_client import StorageClient
from storage_models import ObjectMetadataRequest, ObjectMetadataResponse
from azure.core.exceptions import ResourceNotFoundError

def object_metadata(request: ObjectMetadataRequest) -> ObjectMetadataResponse:
    client = StorageClient().get_blob_service_client()
    blob_client = client.get_blob_client(container=request.container_name, blob=request.blob_name)

    try:
        properties = blob_client.get_blob_properties()
        return ObjectMetadataResponse(
            metadata=properties.metadata if properties.metadata else {},
            size=properties.size,
            last_modified=properties.last_modified.isoformat() if properties.last_modified else "",
            etag=properties.etag
        )
    except ResourceNotFoundError:
        raise FileNotFoundError(f"Object '{request.blob_name}' not found in container '{request.container_name}'.")
    except Exception as e:
        raise RuntimeError(f"Failed to retrieve object metadata: {e}")

from storage_client import StorageClient
from storage_models import ListPrefixRequest, ListPrefixResponse

def list_prefix(request: ListPrefixRequest) -> ListPrefixResponse:
    client = StorageClient().get_blob_service_client()
    container_client = client.get_container_client(request.container_name)

    blob_names = []
    try:
        for blob in container_client.list_blobs(name_starts_with=request.prefix):
            blob_names.append(blob.name)
    except Exception as e:
        raise RuntimeError(f"Failed to list blobs with prefix: {e}")

    return ListPrefixResponse(blob_names=blob_names)
